import{_ as a,o as i,c as n,ai as t}from"./chunks/framework.BxxKhjs3.js";const l="/pub-blog/assets/image-20241219110118201.BvAeoV6z.png",e="data:image/png;base64,",p="data:image/png;base64,",A="data:image/png;base64,",o=JSON.parse('{"title":"12-字符串类型","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/12-字符串类型/12-字符串类型.md","filePath":"仓颉入门到实战/12-字符串类型/12-字符串类型.md","lastUpdated":1734580776000,"__rawMarkdown":"# 12-字符串类型\\n\\n字符串类型使用 `String` 表示，用于表达完整文本数据，它的本质其实由一串 Unicode 字符组合而成。\\n\\n仓颉中的字符串字面量分为三类：单行字符串字面量，多行字符串字面量，多行原始字符串字面量。\\n\\n## 字符串字面量\\n\\n### 单行字符串字面量\\n\\n单行字符串字面量的意思是可以定义的字符串是**单行**的。可以使用单引号和双引号，内容中也支持**转移字符**\\n\\n```javascript\\npackage pro\\n\\nmain() {\\n    //   单行 \\n    let str1 = \\"1 单行\\" // 双引号\\n    let str2 = \'2 单行\' // 单引号\\n\\n    // 单引号中可以放双引号 \\n    let str3 = \'3 单行和\\"双行\\"\'\\n    // 反之也可以\\n    let str4 = \\"4 单行和\'双行\'\\"\\n\\n    // 使用转义字符\\n    let str5 = \\"5 单行 \\\\\\"也能使用双引号了 \\\\n\\"\\n    print(str5)\\n    let str6 = \\"6 单行 也能换行了 \\\\n 换行 \\"\\n    print(str6)\\n}\\n\\n```\\n\\n![image-20241219110118201](12-%E5%AD%97%E7%AC%A6%E4%B8%B2%E7%B1%BB%E5%9E%8B.assets/image-20241219110118201.png)\\n\\n\\n\\n### 多行字符串字面量\\n\\n多行字符串字面量可以支持多行显示，这个是它和 单行字符串字面量最大的区别。\\n\\n符合有两种\\n\\n1. 三个 单引号  \\n\\n   ```\\n   \'\'\'\\n   内容\\n   \'\'\'\\n   ```\\n\\n2. 三个 双引号\\n\\n   ```\\n   \\"\\"\\"\\n   内容\\n   \\"\\"\\"\\n   ```\\n\\n   \\n\\n\\n\\n**示例代码**\\n\\n```javascript\\n    let str7 = \\"\\"\\"\\n    A \\n    B \\n    C\\n\\"\\"\\"\\n    print(str7)\\n```\\n\\n![image-20241219110510351](12-%E5%AD%97%E7%AC%A6%E4%B8%B2%E7%B1%BB%E5%9E%8B.assets/image-20241219110510351.png)\\n\\n### 多行原始字符串字面量\\n\\n多行原始字符串字面量的特点是里面存放的内容都会原样输出，包括转义字符。\\n\\n它定义的方法是1个或者多个#开头，后面跟一个单引号或者一个双引号。比如\\n\\n```javascript\\n#\'abc\'#\\n#\\"\\na\\nb\\nc\\n\\"#\\n\\n######\'a\\\\nb\'######\\n```\\n\\n示例\\n\\n```javascript\\n    // 多行原始\\n    let str8 = #\'\\n    A\\n\\n    B\\n\\n    C\\\\nD\\n    \'#\\n    print(str8)\\n```\\n\\n![image-20241219111051681](12-%E5%AD%97%E7%AC%A6%E4%B8%B2%E7%B1%BB%E5%9E%8B.assets/image-20241219111051681.png)\\n\\n## 插值字符串\\n\\n插值字符串可以让我们在单行字符串和多行字符串中来冲入我们想要的内容，帮忙我们处理字符串。\\n\\n```\\n\'a ${变量} bc\'\\n\\n\'a ${\'你好\'} bc\'\\n```\\n\\n示例\\n\\n```javascript\\n        // 多行\\n        let str7 = \\"\\"\\"\\n        A \\n        ${\'EE\'}\\n        B \\n        C\\n    \\"\\"\\"\\n        print(str7)\\n```\\n\\n![image-20241219113019961](12-%E5%AD%97%E7%AC%A6%E4%B8%B2%E7%B1%BB%E5%9E%8B.assets/image-20241219113019961.png)\\n\\n## 字符串类型支持的操作\\n\\n字符串类型支持使用关系操作符进行比较，支持使用 `+` 进行拼接。下面的例子展示了字符串类型的判等和拼接：\\n\\n```javascript\\nmain() {\\n    let s1 = \\"abc\\"\\n    var s2 = \\"ABC\\"\\n    let r1 = s1 == s2\\n    println(\\"The result of \'abc\' == \'ABC\' is: ${r1}\\")\\n    let r2 = s1 + s2\\n    println(\\"The result of \'abc\' + \'ABC\' is: ${r2}\\")\\n}\\n```\\n\\n编译并执行上述代码，输出结果为：\\n\\n```javascript\\nThe result of \'abc\' == \'ABC\' is: false\\nThe result of \'abc\' + \'ABC\' is: abcABC\\n```\\n\\n字符串还支持其他常见操作，例如拆分、替换等。\\n\\n\\n\\n\\n\\n## 常见的转义字符 \\n\\n| 转义字符 | 意义                                                         | ASCII码值（十进制） |\\n| -------- | ------------------------------------------------------------ | ------------------- |\\n| \\\\a       | 响铃(BEL)                                                    | 007                 |\\n| \\\\b       | 退格(BS) ，将当前位置移到前一列                              | 008                 |\\n| \\\\f       | 换页(FF)，将当前位置移到下页开头                             | 012                 |\\n| \\\\n       | 换行(LF) ，将当前位置移到下一行开头                          | 010                 |\\n| \\\\r       | [回车](https://baike.baidu.com/item/回车/459029?fromModule=lemma_inlink)(CR) ，将当前位置移到本行开头 | 013                 |\\n| \\\\t       | 水平制表(HT) （跳到下一个TAB位置）                           | 009                 |\\n| \\\\v       | 垂直制表(VT)                                                 | 011                 |\\n| \\\\\\\\       | 代表一个反斜线字符\\"\\\\\\"                                        | 092                 |\\n| \\\\\'       | 代表一个单引号（撇号）字符                                   | 039                 |\\n| \\\\\\"       | 代表一个双引号字符                                           | 034                 |\\n| \\\\?       | 代表一个问号                                                 | 063                 |\\n| \\\\0       | 空字符(NUL)                                                  | 000                 |\\n| \\\\ddd     | 1到3位[八进制](https://baike.baidu.com/item/八进制/4230825?fromModule=lemma_inlink)数所代表的任意字符 | 三位八进制          |\\n| \\\\xhh     | [十六进制](https://baike.baidu.com/item/十六进制/4162457?fromModule=lemma_inlink)所代表的任意字符 | 十六进制            |"}'),r={name:"仓颉入门到实战/12-字符串类型/12-字符串类型.md"};function h(k,s,d,g,E,c){return i(),n("div",null,[...s[0]||(s[0]=[t("",36)])])}const B=a(r,[["render",h]]);export{o as __pageData,B as default};
